use kimo_core::commands::{Session,dispatch};use serde_json::json;
fn setup()->(Session,serde_json::Value,serde_json::Value){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":32,"fps":25})).unwrap();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let mut clips=Vec::new();for start in [0,1]{clips.push(dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"solid","color":[0.1,0.2,0.3],"start":start,"duration":1})).unwrap()["clip_id"].clone())}(s,clips[0].clone(),clips[1].clone())}
fn shared(s:&mut Session,id:&str,stops:f64){dispatch(s,"create_shared_grade_graph",&json!({"id":id})).unwrap();dispatch(s,"add_node",&json!({"shared_graph_id":id,"node_id":"a","kind":"grade","effect_kind":"exposure","params":{"stops":stops}})).unwrap();dispatch(s,"set_grade_output",&json!({"shared_graph_id":id,"node_id":"a"})).unwrap();}
fn pixel(s:&Session,t:f64)->f32{kimo_core::render::render_frame(&s.project,t,&kimo_core::render::Cache::new()).unwrap().d[0]}
#[test]fn shared_two_clips_live_edits_and_clock(){let(mut s,a,b)=setup();shared(&mut s,"shared",1.);for c in [&a,&b]{dispatch(&mut s,"bind_shared_grade_graphs",&json!({"clip_id":c,"graphs":["shared"]})).unwrap();}assert_eq!(pixel(&s,0.),0.2);assert_eq!(pixel(&s,1.),0.2);dispatch(&mut s,"set_node_param",&json!({"shared_graph_id":"shared","node_id":"a","parameter":"stops","property":{"base":0,"keys":[{"t":0,"v":0},{"t":1,"v":1}]}})).unwrap();assert_eq!(pixel(&s,0.),0.1);assert_eq!(pixel(&s,1.),0.1);assert!((pixel(&s,0.5)-0.1*2f32.sqrt()).abs()<1e-7);assert!((pixel(&s,1.5)-0.1*2f32.sqrt()).abs()<1e-7);assert!(dispatch(&mut s,"remove_shared_grade_graph",&json!({"id":"shared"})).is_err());let bytes=serde_json::to_vec(&s.project).unwrap();let p:kimo_core::model::Project=serde_json::from_slice(&bytes).unwrap();assert_eq!(serde_json::to_value(p.grade_scopes).unwrap(),serde_json::to_value(&s.project.grade_scopes).unwrap());}
#[test]fn group_order_membership_timeline_no_graph(){let(mut s,a,b)=setup();let before=pixel(&s,0.);shared(&mut s,"up",1.);shared(&mut s,"down",-1.);let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["groups"]=json!([{"id":"g","clips":[a],"graphs":["up"],"bypass":false}]);scopes["timeline"]=json!(["down"]);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();assert_eq!(pixel(&s,0.),before);assert_eq!(pixel(&s,1.),0.05);let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["groups"][0]["bypass"]=json!(true);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();assert_eq!(pixel(&s,0.),0.05);let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["timeline"]=json!([]);scopes["groups"]=json!([]);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();assert_eq!(pixel(&s,0.),before);let _=b;}
#[test]fn adjustment_shared_and_no_double_nested_timeline(){let(mut s,a,_)=setup();shared(&mut s,"up",1.);let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let adj=dispatch(&mut s,"add_adjustment_layer",&json!({"track_id":t,"start":0,"duration":1})).unwrap();{dispatch(&mut s,"bind_shared_grade_graphs",&json!({"clip_id":adj["clip_id"],"graphs":["up"]})).unwrap();assert_eq!(pixel(&s,0.),0.2);}let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["clip_bindings"]=json!({});scopes["timeline"]=json!(["up"]);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();let cache=kimo_core::render::Cache::new();let matte=kimo_core::render::render_clip_alone(&s.project,a.as_str().unwrap(),0.,&cache).unwrap();assert_eq!(matte.d[0],0.1);assert_eq!(pixel(&s,0.),0.2);}
#[test]fn missing_references_transactional(){let(mut s,a,_)=setup();let before=serde_json::to_value(&s.project).unwrap();assert!(dispatch(&mut s,"bind_shared_grade_graphs",&json!({"clip_id":a,"graphs":["missing"]})).is_err());assert_eq!(before,serde_json::to_value(&s.project).unwrap());assert!(dispatch(&mut s,"set_grade_scopes",&json!({"scopes":{"graphs":{},"groups":[{"id":"g","clips":["bad"],"graphs":[]}],"timeline":[]}})).is_err());}
#[test]fn group_order_is_not_commutative_and_nested_timeline_once(){let(mut s,a,_)=setup();shared(&mut s,"exposure",1.);shared(&mut s,"inverse",0.);let mut node=dispatch(&mut s,"inspect_grade_graph",&json!({"shared_graph_id":"inverse"})).unwrap()["graph"]["nodes"]["a"].clone();node["effect"]["kind"]=json!("invert");node["effect"]["params"]=json!({});dispatch(&mut s,"set_grade_node",&json!({"shared_graph_id":"inverse","node":node})).unwrap();let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["groups"]=json!([{"id":"1","clips":[a],"graphs":["exposure"]},{"id":"2","clips":[a],"graphs":["inverse"]}]);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();assert!((pixel(&s,0.)-0.8).abs()<1e-7);let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["groups"].as_array_mut().unwrap().reverse();dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();assert!((pixel(&s,0.)-1.8).abs()<1e-7);
let(mut s,a,_)=setup();shared(&mut s,"up",1.);let child=s.project.find_clip_mut(a.as_str().unwrap()).unwrap().clone();std::sync::Arc::make_mut(&mut s.project.tracks[0].clips[0]).source=kimo_core::model::Source::Precomp{tracks:vec![kimo_core::model::Track{id:"nested".into(),clips:vec![kimo_core::model::Clip{id:"child".into(),..child}.into()],locked:false,muted:false,solo:false,name:String::new()}]};let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["timeline"]=json!(["up"]);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();assert_eq!(pixel(&s,0.),0.2);}
#[test]fn real_scoped_reference_repeat(){if !std::path::Path::new("/tmp/subject-source.png").exists(){return}let(mut s,_,_)=setup();s.project.tracks.clear();s.project.width=640;s.project.height=360;let a=dispatch(&mut s,"import_media",&json!({"path":"/tmp/subject-source.png"})).unwrap()["asset_id"].clone();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"media","asset_id":a,"start":0,"duration":0.08})).unwrap()["clip_id"].clone();let mut cache=kimo_core::render::Cache::new();kimo_core::render::prepare_at(&s.project,&mut cache,Some(0.)).unwrap();let raw=kimo_core::render::render_frame(&s.project,0.,&cache).unwrap();shared(&mut s,"clip",0.25);shared(&mut s,"group",0.125);shared(&mut s,"timeline",-0.25);dispatch(&mut s,"bind_shared_grade_graphs",&json!({"clip_id":c,"graphs":["clip"]})).unwrap();let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["groups"]=json!([{"id":"g","clips":[c],"graphs":["group"]}]);scopes["timeline"]=json!(["timeline"]);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();let after=kimo_core::render::render_frame(&s.project,0.,&cache).unwrap();let mut expected=kimo_core::effects::Frame{w:raw.w,h:raw.h,d:raw.d.clone()};for stops in [0.25,0.125,-0.25]{let mut p=kimo_core::effects::Params::new();p.insert("stops".into(),kimo_core::keyframe::Prop::new(stops));kimo_core::effects::apply("exposure",&p,&Default::default(),&mut expected,0.,0).unwrap();}assert_eq!(expected.d,after.d);assert_eq!(after.d,kimo_core::render::render_frame(&s.project,0.,&cache).unwrap().d);for(path,f)in[("/tmp/scope-real-before.f32",raw),("/tmp/scope-real-after.f32",after)]{std::fs::write(path,f.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();}}
#[cfg(feature="native-ocio")]
#[test]fn shared_native_domain_and_stale_gamut(){let(mut s,c,_)=setup();shared(&mut s,"native",0.);let mut n=dispatch(&mut s,"inspect_grade_graph",&json!({"shared_graph_id":"native"})).unwrap()["graph"]["nodes"]["a"].clone();n["effect"]["kind"]=json!("film_soft_shoulder");n["effect"]["params"]=json!({});n["effect"]["strings"]=json!({"ocio_domain":"display-referred","ocio_config":concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio"),"ocio_working_space":"ACEScg","ocio_linear_space":"ACEScg","ocio_display_space":"DisplayGamma2"});dispatch(&mut s,"set_grade_node",&json!({"shared_graph_id":"native","node":n})).unwrap();dispatch(&mut s,"bind_shared_grade_graphs",&json!({"clip_id":c,"graphs":["native"]})).unwrap();let v=pixel(&s,0.);assert!((v-0.1).abs()<1e-6);assert_eq!(v,pixel(&s,0.));}
#[test]fn split_keeps_shared_group_and_delete_clears_refs(){let(mut s,c,_)=setup();shared(&mut s,"up",1.);dispatch(&mut s,"bind_shared_grade_graphs",&json!({"clip_id":c,"graphs":["up"]})).unwrap();let mut scopes=serde_json::to_value(&s.project.grade_scopes).unwrap();scopes["groups"]=json!([{"id":"g","clips":[c],"graphs":["up"]}]);dispatch(&mut s,"set_grade_scopes",&json!({"scopes":scopes})).unwrap();let right=dispatch(&mut s,"split_clip",&json!({"clip_id":c,"at":0.5})).unwrap()["right_clip_id"].clone();assert_eq!(pixel(&s,0.25),0.4);assert_eq!(pixel(&s,0.75),0.4);dispatch(&mut s,"delete_clip",&json!({"clip_id":right})).unwrap();assert!(s.project.dangling_refs().is_empty());assert!(!s.project.grade_scopes.groups[0].clips.iter().any(|x|x==right.as_str().unwrap()));}
